(42929, 523, 352, '<td valign="top">Nice!  I''m wondering if a polarizing filter would have made the harsh reflections on the right a little less harsh.</td>', 'Nice!  I''m wondering if a polarizing filter would have made the harsh reflections on the right a little less harsh.', '2002-04-01 01:34:00.000000', NULL, 1),
(42930, 523, 705, '<td valign="top">a great composition, but the glare on the building is too much; girders above are quite rich; I want this image to be sharper</td>', 'a great composition, but the glare on the building is too much; girders above are quite rich; I want this image to be sharper', '2002-04-01 02:22:00.000000', NULL, 1),
(42931, 523, 245, '<td valign="top">just a touch too blown-out, if it were just the windows it''d look better, but too much of the wall''s detail is lost.</td>', 'just a touch too blown-out, if it were just the windows it''d look better, but too much of the wall''s detail is lost.', '2002-04-01 02:32:00.000000', NULL, 1),
(42932, 523, 270, '<td valign="top">Lovely shadows, great perspective.</td>', 'Lovely shadows, great perspective.', '2002-04-01 02:46:00.000000', NULL, 1),
(42933, 523, 291, '<td valign="top">Nice B&amp;W,</td>', 'Nice B&W,', '2002-04-01 02:47:00.000000', NULL, 1),
(42934, 523, 1, '<td valign="top">Very nicely done.  Initially looking at it, I thought it was inside, maybe in a library, but after staring at it for awhile, I think it''s outside.  All the same, it''s a great how.</td>', 'Very nicely done.  Initially looking at it, I thought it was inside, maybe in a library, but after staring at it for awhile, I think it''s outside.  All the same, it''s a great how.', '2002-04-01 08:12:00.000000', NULL, 1),
(42935, 523, 472, '<td valign="top">i like theq industrial film noir look to this</td>', 'i like theq industrial film noir look to this', '2002-04-01 08:43:00.000000', NULL, 1),
(42936, 523, 312, '<td valign="top">i really like the shadows and angle on this photo. seems a tad underexposed in areas, but i think you''d risk blowing out the right side of the building with more exposure.</td>', 'i really like the shadows and angle on this photo. seems a tad underexposed in areas, but i think you''d risk blowing out the right side of the building with more exposure.', '2002-04-01 12:05:00.000000', NULL, 1),
(42937, 523, 441, '<td valign="top">good shot - shadows at base detract.</td>', 'good shot - shadows at base detract.', '2002-04-01 12:53:00.000000', NULL, 1),
(42938, 523, 259, '<td valign="top">great shadows</td>', 'great shadows', '2002-04-01 15:36:00.000000', NULL, 1),
(42939, 523, 332, '<td valign="top">I like this picture. Maby a bit more contrast would make it perfect. I think it looks better if you flip it horizontal.</td>', 'I like this picture. Maby a bit more contrast would make it perfect. I think it looks better if you flip it horizontal.', '2002-04-01 16:26:00.000000', NULL, 1),
(42940, 523, 327, '<td valign="top">Very nice. Love the b&amp;w.....cold looking.</td>', 'Very nice. Love the b&w.....cold looking.', '2002-04-01 18:36:00.000000', NULL, 1),
(42941, 523, 244, '<td valign="top">Nice composition I like your use of light</td>', 'Nice composition I like your use of light', '2002-04-01 20:30:00.000000', NULL, 1),
(42942, 523, 378, '<td valign="top">Can''t tell you why, but I find it has a strong mood.</td>', 'Can''t tell you why, but I find it has a strong mood.', '2002-04-02 08:38:00.000000', NULL, 1),
(42943, 523, 549, '<td valign="top">love the lighting and the shadows and the use of black and white. All good choices. And the angle is dynamic.</td>', 'love the lighting and the shadows and the use of black and white. All good choices. And the angle is dynamic.', '2002-04-02 09:05:00.000000', NULL, 1),
(42944, 523, 656, '<td valign="top">classic black and white/ industrial shot.  Great converging lines.  Seems tilted slightly though.</td>', 'classic black and white/ industrial shot.  Great converging lines.  Seems tilted slightly though.', '2002-04-02 14:39:00.000000', NULL, 1),
(42945, 523, 346, '<td valign="top">Amazing shot! great use of monochrome here, along with the play of shadows.</td>', 'Amazing shot! great use of monochrome here, along with the play of shadows.', '2002-04-02 16:48:00.000000', NULL, 1),
(42946, 523, 301, '<td valign="top">I love it - there is an eerieness and yet serenity to the picture</td>', 'I love it - there is an eerieness and yet serenity to the picture', '2002-04-03 07:28:00.000000', NULL, 1),
(42947, 523, 156, '<td valign="top">nice, perhaps a little too dark tho</td>', 'nice, perhaps a little too dark tho', '2002-04-03 10:15:00.000000', NULL, 1),
(42948, 523, 356, '<td valign="top">I would have tried to crop off more at the bottom.  There isn''t much going on there.</td>', 'I would have tried to crop off more at the bottom.  There isn''t much going on there.', '2002-04-03 10:30:00.000000', NULL, 1),
(42949, 523, 279, '<td valign="top">Wow. Very nice!</td>', 'Wow. Very nice!', '2002-04-03 12:59:00.000000', NULL, 1),
(42950, 523, 637, '<td valign="top">A little too dark for my tastes, yet stirringly effective.</td>', 'A little too dark for my tastes, yet stirringly effective.', '2002-04-03 13:43:00.000000', NULL, 1),
(42951, 523, 772, '<td valign="top">I particularly like the depth perception and offset horizon in this photo... not to mention that i love black and white... Kudos to the photographer!</td>', 'I particularly like the depth perception and offset horizon in this photo... not to mention that i love black and white... Kudos to the photographer!', '2002-04-03 16:05:00.000000', NULL, 1),
(42952, 523, 447, '<td valign="top">Interesting and fine detail. I would have cropped the bottom part out though.</td>', 'Interesting and fine detail. I would have cropped the bottom part out though.', '2002-04-06 20:46:00.000000', NULL, 1),
(42953, 523, 543, '<td valign="top">Very dramatic.  Everything just grows out of the shadows, and all the lines lead to the light.  Nice work.</td>', 'Very dramatic.  Everything just grows out of the shadows, and all the lines lead to the light.  Nice work.', '2002-04-07 09:30:00.000000', NULL, 1),
(42954, 523, 179, '<td valign="top">One of my top 3. Light, angle and subject come together flawlessly. Great Job! Good Luck!</td>', 'One of my top 3. Light, angle and subject come together flawlessly. Great Job! Good Luck!', '2002-04-07 15:38:00.000000', NULL, 1),
(42955, 523, 2, '<td valign="top">Very nice picture -- great use of lighting.</td>', 'Very nice picture -- great use of lighting.', '2002-04-07 21:29:00.000000', NULL, 1),
(42956, 524, 705, '<td valign="top">nice framing horizontally, but the vertical...hm, the bridge gets lost; difficult light to shoot in, I think, eh?  the entire effect is washed out, too cool.</td>', 'nice framing horizontally, but the vertical...hm, the bridge gets lost; difficult light to shoot in, I think, eh?  the entire effect is washed out, too cool.', '2002-04-01 02:17:00.000000', NULL, 1),
(42957, 524, 245, '<td valign="top">this could look really striking on a a day that isn''t as drab. I''d have raised the camera a bit, so the horizon was lower.</td>', 'this could look really striking on a a day that isn''t as drab. I''d have raised the camera a bit, so the horizon was lower.', '2002-04-01 02:33:00.000000', NULL, 1),
(42958, 524, 270, '<td valign="top">Lovely location.  Try under-exposing it manually next time so the trees aren''t quite so washed out.</td>', 'Lovely location.  Try under-exposing it manually next time so the trees aren''t quite so washed out.', '2002-04-01 03:13:00.000000', NULL, 1),
(42959, 524, 472, '<td valign="top">good compo</td>', 'good compo', '2002-04-01 08:46:00.000000', NULL, 1),
(42960, 524, 509, '<td valign="top">I think it would look nicer if you had zoomed in a bit more.  That would put a greater emphasis on the bridge, and the bridge''s reflection in the water might have more impact</td>', 'I think it would look nicer if you had zoomed in a bit more.  That would put a greater emphasis on the bridge, and the bridge''s reflection in the water might have more impact', '2002-04-01 11:37:00.000000', NULL, 1),
(42961, 524, 641, '<td valign="top">I like the soft look to it.</td>', 'I like the soft look to it.', '2002-04-01 12:59:00.000000', NULL, 1),
(42962, 524, 536, '<td valign="top">Can you run Auto Levels on your copy and see if you like it? It really seemed to make this photo more alive. Nice location. I would be interested in seeing how the mood changes over the seasons. <br/></td>', 'Can you run Auto Levels on your copy and see if you like it? It really seemed to make this photo more alive. Nice location. I would be interested in seeing how the mood changes over the seasons. ', '2002-04-01 13:15:00.000000', NULL, 1),
(42963, 524, 102, '<td valign="top">Nice shot!  Might have looked better if you had run a sharpen or sharpen edges, but the reflection is really impressive.  Also, toning down the Levels (especially in the sky) might have helped.</td>', 'Nice shot!  Might have looked better if you had run a sharpen or sharpen edges, but the reflection is really impressive.  Also, toning down the Levels (especially in the sky) might have helped.', '2002-04-01 16:15:00.000000', NULL, 1),
(42964, 524, 661, '<td valign="top">Very clear!</td>', 'Very clear!', '2002-04-01 19:29:00.000000', NULL, 1),
(42965, 524, 428, '<td valign="top">This is great! I love the reflections in the water and the road leading to the bridge. Excellent composition and focus.</td>', 'This is great! I love the reflections in the water and the road leading to the bridge. Excellent composition and focus.', '2002-04-01 22:44:00.000000', NULL, 1),
(42966, 524, 1, '<td valign="top">A bit over-exposed it seems, but it''s a nice idea.  Surprisingly haven''t seen too many bridges.</td>', 'A bit over-exposed it seems, but it''s a nice idea.  Surprisingly haven''t seen too many bridges.', '2002-04-02 09:42:00.000000', NULL, 1),
(42967, 524, 346, '<td valign="top">really nice subject. Moving the bridge either a little up/down might have made a stronger composition.</td>', 'really nice subject. Moving the bridge either a little up/down might have made a stronger composition.', '2002-04-02 16:40:00.000000', NULL, 1),
(42968, 524, 637, '<td valign="top">I like the reflection, but wish there was a more interesting sky.</td>', 'I like the reflection, but wish there was a more interesting sky.', '2002-04-03 14:22:00.000000', NULL, 1),
(42969, 524, 772, '<td valign="top">This would make a nice panoramic image with just the bridge and it''s reflection in the water... I like to use a polarizer in these lighting conditions...</td>', 'This would make a nice panoramic image with just the bridge and it''s reflection in the water... I like to use a polarizer in these lighting conditions...', '2002-04-03 16:23:00.000000', NULL, 1),
(42970, 524, 113, '<td valign="top">I love this photo.</td>', 'I love this photo.', '2002-04-05 02:41:00.000000', NULL, 1),
(42971, 524, 797, '<td valign="top">very nice zig-zag perspective. would''ve made a lovely monochrome without the grass below.</td>', 'very nice zig-zag perspective. would''ve made a lovely monochrome without the grass below.', '2002-04-06 23:33:00.000000', NULL, 1),
(42972, 524, 2, '<td valign="top">This picture might have been better at a different time of day -- the white is a little overwhelming.</td>', 'This picture might have been better at a different time of day -- the white is a little overwhelming.', '2002-04-07 21:26:00.000000', NULL, 1),
(42973, 525, 705, '<td valign="top">the church and disorientation, hm.  it''s creepy (good); I think that _something_ needs to be sharply in focus, although I like the out-of-focus margin</td>', 'the church and disorientation, hm.  it''s creepy (good); I think that _something_ needs to be sharply in focus, although I like the out-of-focus margin', '2002-04-01 02:16:00.000000', NULL, 1),
(42974, 525, 245, '<td valign="top">This is a great photo. That railing is true as an arrow! What did you do to create this? A special lens? Zooming while shooting? Inquiring minds want to know!</td>', 'This is a great photo. That railing is true as an arrow! What did you do to create this? A special lens? Zooming while shooting? Inquiring minds want to know!', '2002-04-01 02:19:00.000000', NULL, 1),
(42975, 525, 291, '<td valign="top">Holy Mackrel!, out of focus, no contrast and the framing doesn''t make sense</td>', 'Holy Mackrel!, out of focus, no contrast and the framing doesn''t make sense', '2002-04-01 03:06:00.000000', NULL, 1),
(42976, 525, 472, '<td valign="top">interesting blur filter effect enhances idea of entering holy place</td>', 'interesting blur filter effect enhances idea of entering holy place', '2002-04-01 07:45:00.000000', NULL, 1),
(42977, 525, 441, '<td valign="top">homemade wideangle? - good idea</td>', 'homemade wideangle? - good idea', '2002-04-01 11:23:00.000000', NULL, 1),
(42978, 525, 203, '<td valign="top">Umpteen tilts so far and none have seemed to add to the composition.</td>', 'Umpteen tilts so far and none have seemed to add to the composition.', '2002-04-01 13:52:00.000000', NULL, 1),
(42979, 525, 102, '<td valign="top">The blur effect is done fairly well, but the blurring implies (to me) a sense of foreboding, or of fear.  The title doesn''t match that, if anything the title is a little bit vanilla.  Interesting shot though.</td>', 'The blur effect is done fairly well, but the blurring implies (to me) a sense of foreboding, or of fear.  The title doesn''t match that, if anything the title is a little bit vanilla.  Interesting shot though.', '2002-04-01 16:04:00.000000', NULL, 1),
(42980, 525, 544, '<td valign="top">wow! nice blur/panoramic effect on the doors.</td>', 'wow! nice blur/panoramic effect on the doors.', '2002-04-01 18:31:00.000000', NULL, 1),
(42981, 525, 661, '<td valign="top">Interesting subject.  I''m not much for the rotation.  Also the image wasn''t sharp. (on purpose?)</td>', 'Interesting subject.  I''m not much for the rotation.  Also the image wasn''t sharp. (on purpose?)', '2002-04-01 19:20:00.000000', NULL, 1),
(42982, 525, 536, '<td valign="top">Interesting and nice angle.  Good composition.  I''m new at this so some of my comments may make you roll your eyes. Humor the n00b. :) Your white balance seems a little off.  Last week Mousie taught me about using Sharpen.  I think Sharpen would help here too.  I''m not sure if your distortion is intentional or not. It works for this photo.  If it isn''t intentional, changing your focal length will help it in cases (like the challenge) when you can''t use software to correct it. Overall - a very pleasing photo.  I enjoyed it.</td>', 'Interesting and nice angle.  Good composition.  I''m new at this so some of my comments may make you roll your eyes. Humor the n00b. :) Your white balance seems a little off.  Last week Mousie taught me about using Sharpen.  I think Sharpen would help here too.  I''m not sure if your distortion is intentional or not. It works for this photo.  If it isn''t intentional, changing your focal length will help it in cases (like the challenge) when you can''t use software to correct it. Overall - a very pleasing photo.  I enjoyed it.', '2002-04-02 12:02:00.000000', NULL, 1),
(42983, 525, 346, '<td valign="top">beautiful composition! love the effect that you got. When the challenge is over, I want to know how you did that.</td>', 'beautiful composition! love the effect that you got. When the challenge is over, I want to know how you did that.', '2002-04-02 12:52:00.000000', NULL, 1),
(42984, 525, 113, '<td valign="top">Not sure how you did this, but I like the photo.</td>', 'Not sure how you did this, but I like the photo.', '2002-04-03 07:34:00.000000', NULL, 1),
(42985, 525, 772, '<td valign="top">I am a firm believer of tilting my camera for effect and I like this photo because of that.  I would love to see the image without the lens filter in place...</td>', 'I am a firm believer of tilting my camera for effect and I like this photo because of that.  I would love to see the image without the lens filter in place...', '2002-04-03 16:22:00.000000', NULL, 1),
(42986, 525, 637, '<td valign="top">Don''t understand the value of the tilt<br/></td>', 'Don''t understand the value of the tilt', '2002-04-03 19:09:00.000000', NULL, 1),
(42987, 525, 361, '<td valign="top">Interesting photo / angle. It''s really blurry around the edges, though. Really distracting... to me anyway.</td>', 'Interesting photo / angle. It''s really blurry around the edges, though. Really distracting... to me anyway.', '2002-04-04 15:00:00.000000', NULL, 1),
(42988, 525, 205, '<td valign="top">your "fish eye" sucks</td>', 'your "fish eye" sucks', '2002-04-06 16:19:00.000000', NULL, 1),
(42989, 525, 813, '<td valign="top">An odd yet compelling image.</td>', 'An odd yet compelling image.', '2002-04-06 23:02:00.000000', NULL, 1),
(42990, 525, 820, '<td valign="top">Is that radial blur I see?</td>', 'Is that radial blur I see?', '2002-04-07 12:27:00.000000', NULL, 1),
(42991, 525, 139, '<td valign="top">This was an amazing photo. I''m baffled as to why it was rated so low.</td>', 'This was an amazing photo. I''m baffled as to why it was rated so low.', '2002-04-08 01:31:00.000000', NULL, 0),
(42992, 525, 1, '<td valign="top">I am slightly shocked that it appeared way down the list too.  I believe I gave it a 9 or 10.</td>', 'I am slightly shocked that it appeared way down the list too.  I believe I gave it a 9 or 10.', '2002-04-08 06:39:00.000000', NULL, 0),
(42993, 525, 641, '<td valign="top">Thanks for the comments everyone, I am very grateful. It was interesting to hear the different views. I''ll try to answer as many of the questions about it I can.  I took the shot with a new wide angle lens that I got, I wasn''t used to using it and was playing around with it. I agree it was a bit blurry, but I kinda liked the effect so stuck with it in this shot. The reason for the angle framing, was that I took one of it framed normally and it was just too boring. I happen to like the feel the angle shot gave it so stuck with that too. I do remember doing a little bit of fooling with the levels to bring out the cream color in the door framing, but not much. I liked the subdued color to it.<br/><br/>Photographing churches is a favorite passtime of mine. I love their architecture and beauty.</td>', 'Thanks for the comments everyone, I am very grateful. It was interesting to hear the different views. I''ll try to answer as many of the questions about it I can.  I took the shot with a new wide angle lens that I got, I wasn''t used to using it and was playing around with it. I agree it was a bit blurry, but I kinda liked the effect so stuck with it in this shot. The reason for the angle framing, was that I took one of it framed normally and it was just too boring. I happen to like the feel the angle shot gave it so stuck with that too. I do remember doing a little bit of fooling with the levels to bring out the cream color in the door framing, but not much. I liked the subdued color to it.Photographing churches is a favorite passtime of mine. I love their architecture and beauty.', '2002-04-09 09:23:00.000000', NULL, 0),
(42994, 525, 1034, '<td valign="top">hmm.... you might think i''m stupid, but is that image really done with a kodak dc3400?  i''m borrowing one that my friend lets me bowwow and i don''t think this thing can take lenses.  hmm... am i wrong?</td>', 'hmm.... you might think i''m stupid, but is that image really done with a kodak dc3400?  i''m borrowing one that my friend lets me bowwow and i don''t think this thing can take lenses.  hmm... am i wrong?', '2002-04-14 01:53:00.000000', NULL, 0),
(43009, 527, 352, '<td valign="top">Sorry, but tilted pictures annoy me to no end!</td>', 'Sorry, but tilted pictures annoy me to no end!', '2002-04-01 01:50:00.000000', NULL, 1),
(43010, 527, 245, '<td valign="top">the focus is too soft, and I''d have tried to get a little more of the right, um... column into the picture. The picture looks really compressed on my screen, too.</td>', 'the focus is too soft, and I''d have tried to get a little more of the right, um... column into the picture. The picture looks really compressed on my screen, too.', '2002-04-01 02:36:00.000000', NULL, 1),
(43011, 527, 270, '<td valign="top">Almost, but the JPEG artifacting combined with everything being off-kilter makes it hard to look at.</td>', 'Almost, but the JPEG artifacting combined with everything being off-kilter makes it hard to look at.', '2002-04-01 03:05:00.000000', NULL, 1),
(43012, 527, 472, '<td valign="top">interesting. too bad the picture is blurry.</td>', 'interesting. too bad the picture is blurry.', '2002-04-01 08:44:00.000000', NULL, 1),
(43013, 527, 351, '<td valign="top">A good shot but WAY too much jpeg artifacting.  your image is only 43k! next time, use more of the 150k we''re allowed.</td>', 'A good shot but WAY too much jpeg artifacting.  your image is only 43k! next time, use more of the 150k we''re allowed.', '2002-04-01 08:46:00.000000', NULL, 1),
(43014, 527, 509, '<td valign="top">too much jpeg compression, interesting subject</td>', 'too much jpeg compression, interesting subject', '2002-04-01 11:34:00.000000', NULL, 1),
(43015, 527, 441, '<td valign="top">Massive JPEG artifacs here - your compressed file is only 43Kb - unless you intended this result you need to take advantage of the maximum permissable file size of 150Kb - put a posting in Q &amp; A forum if you are unsure how to do this.</td>', 'Massive JPEG artifacs here - your compressed file is only 43Kb - unless you intended this result you need to take advantage of the maximum permissable file size of 150Kb - put a posting in Q & A forum if you are unsure how to do this.', '2002-04-01 12:30:00.000000', NULL, 1),
(43016, 527, 280, '<td valign="top">Too much compression.</td>', 'Too much compression.', '2002-04-01 13:20:00.000000', NULL, 1),
(43017, 527, 203, '<td valign="top">I am sure the tilt is ment to be but it detracts from this photo in my eye.  Others of course will feel the tilt makes this shot.</td>', 'I am sure the tilt is ment to be but it detracts from this photo in my eye.  Others of course will feel the tilt makes this shot.', '2002-04-01 13:30:00.000000', NULL, 1),
(43018, 527, 102, '<td valign="top">The shot is blurry, and the color depth feels kinda flat; probably would have looked better if you were a little farther back to so you could get the right structure fully, and maybe to have a little bit of space around the edges.  (Er.... what language is the title?)</td>', 'The shot is blurry, and the color depth feels kinda flat; probably would have looked better if you were a little farther back to so you could get the right structure fully, and maybe to have a little bit of space around the edges.  (Er.... what language is the title?)', '2002-04-01 16:13:00.000000', NULL, 1),
(43019, 527, 428, '<td valign="top">Too much tilt and a little bit blurry, otherwise I like these "shapes". Is this a monument or something?</td>', 'Too much tilt and a little bit blurry, otherwise I like these "shapes". Is this a monument or something?', '2002-04-01 18:34:00.000000', NULL, 1),
(43020, 527, 705, '<td valign="top">a bit blurry and pixelated; I like the angle; great light; a bit of sky above the point of the highest, er, steeple would be good;</td>', 'a bit blurry and pixelated; I like the angle; great light; a bit of sky above the point of the highest, er, steeple would be good;', '2002-04-01 23:57:00.000000', NULL, 1),
(43021, 527, 330, '<td valign="top">Not sure about tye odd angle.</td>', 'Not sure about tye odd angle.', '2002-04-02 08:43:00.000000', NULL, 1),
(43022, 527, 549, '<td valign="top">almost looks like something out of Star Wars Episode one. A bit on the blurry side. Was this shot from a moving car?</td>', 'almost looks like something out of Star Wars Episode one. A bit on the blurry side. Was this shot from a moving car?', '2002-04-02 09:06:00.000000', NULL, 1),
(43023, 527, 656, '<td valign="top">either not very well focused or lost a lot of detail due to compression</td>', 'either not very well focused or lost a lot of detail due to compression', '2002-04-02 14:48:00.000000', NULL, 1),
(43024, 527, 346, '<td valign="top">blurriness is distracting.</td>', 'blurriness is distracting.', '2002-04-02 17:07:00.000000', NULL, 1),
(43025, 527, 1, '<td valign="top">A seemingly grainy image, at a weird angle.  I figure if you have multiple vertical items, the photo shouldn''t be crooked.  Just my opinion though.</td>', 'A seemingly grainy image, at a weird angle.  I figure if you have multiple vertical items, the photo shouldn''t be crooked.  Just my opinion though.', '2002-04-02 18:16:00.000000', NULL, 1),
(43026, 527, 308, '<td valign="top">The subject seems interesting, but I think it would have bee incredible without the tilt.</td>', 'The subject seems interesting, but I think it would have bee incredible without the tilt.', '2002-04-02 20:07:00.000000', NULL, 1),
(43027, 527, 757, '<td valign="top">this could have been a better picture if it weren''t crooked.</td>', 'this could have been a better picture if it weren''t crooked.', '2002-04-02 21:56:00.000000', NULL, 1),
(43028, 527, 291, '<td valign="top">Rule # 3 "Level horizon"</td>', 'Rule # 3 "Level horizon"', '2002-04-02 23:45:00.000000', NULL, 1),
(43029, 527, 772, '<td valign="top">This is an OK photo...</td>', 'This is an OK photo...', '2002-04-03 16:28:00.000000', NULL, 1),
(43030, 527, 113, '<td valign="top">Very nice.</td>', 'Very nice.', '2002-04-05 02:42:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(43031, 527, 587, '<td valign="top">neat, wish it was clearer.</td>', 'neat, wish it was clearer.', '2002-04-05 16:03:00.000000', NULL, 1),
