(43183, 543, 708, '<td valign="top">i like it, but, what is it?</td>', 'i like it, but, what is it?', '2002-04-02 08:33:00.000000', NULL, 1),
(43184, 543, 549, '<td valign="top">Very nice, but not fair! This is one cool building in it''s own right. Really, you did a great job finding just the right area to shoot! This could be a winner.</td>', 'Very nice, but not fair! This is one cool building in it''s own right. Really, you did a great job finding just the right area to shoot! This could be a winner.', '2002-04-02 08:45:00.000000', NULL, 1),
