(43216, 547, 603, '<td valign="top">the color is very interesting..slightly tilted though..</td>', 'the color is very interesting..slightly tilted though..', '2002-04-01 01:36:00.000000', NULL, 1),
(43217, 547, 291, '<td valign="top">Nice belfry, slightly tilted</td>', 'Nice belfry, slightly tilted', '2002-04-01 02:55:00.000000', NULL, 1),
(43218, 547, 270, '<td valign="top">Nice colors, but a little off-balance.  Although I''m sure many folks will say they hate power lines, I think you could have counter-acted them by tilting everything left a bit.</td>', 'Nice colors, but a little off-balance.  Although I''m sure many folks will say they hate power lines, I think you could have counter-acted them by tilting everything left a bit.', '2002-04-01 03:03:00.000000', NULL, 1),
