(43220, 547, 705, '<td valign="top">nice framing; _almost_ got the beauty of the clouds in the background; the wires are disruptive; the light looks directionless, and doesn''t particularly enhance the cupola.</td>', 'nice framing; _almost_ got the beauty of the clouds in the background; the wires are disruptive; the light looks directionless, and doesn''t particularly enhance the cupola.', '2002-04-01 12:57:00.000000', NULL, 1),
(43221, 547, 203, '<td valign="top">Interesting sky.  Are you as frustrated by wires as I am?</td>', 'Interesting sky.  Are you as frustrated by wires as I am?', '2002-04-01 13:58:00.000000', NULL, 1),
(43222, 547, 661, '<td valign="top">Interesting photo.  The wires detract from the photo.</td>', 'Interesting photo.  The wires detract from the photo.', '2002-04-01 19:42:00.000000', NULL, 1),
(43223, 547, 1, '<td valign="top">Very nice colors and composition.  I''d like to see less of a slant -- is it the leaning tower of pisa?  :)</td>', 'Very nice colors and composition.  I''d like to see less of a slant -- is it the leaning tower of pisa?  :)', '2002-04-01 20:17:00.000000', NULL, 1),
(43224, 547, 549, '<td valign="top">just not interesting enough. Could of used a different angle or time of day.</td>', 'just not interesting enough. Could of used a different angle or time of day.', '2002-04-02 08:51:00.000000', NULL, 1),
(43225, 547, 346, '<td valign="top">obviously it wasn''t possible for this challenge, but the lines in the back are distracting. still a great pic though.</td>', 'obviously it wasn''t possible for this challenge, but the lines in the back are distracting. still a great pic though.', '2002-04-02 12:38:00.000000', NULL, 1),
(43226, 547, 113, '<td valign="top">The highwires don''t help this photo.  Sorry, but it seems a little boring.</td>', 'The highwires don''t help this photo.  Sorry, but it seems a little boring.', '2002-04-03 07:03:00.000000', NULL, 1),
(43227, 547, 772, '<td valign="top">Don''t you hate it when wires ruin a great photo opportunity?  But it''s still a nice photograph :)</td>', 'Don''t you hate it when wires ruin a great photo opportunity?  But it''s still a nice photograph :)', '2002-04-03 16:51:00.000000', NULL, 1),
(43228, 547, 570, '<td valign="top">ugly</td>', 'ugly', '2002-04-04 14:21:00.000000', NULL, 1),
(43229, 547, 428, '<td valign="top">Thanks for all the comments!  It''s not the "leaning tower of Piza" but I guess you could say it is the "leaning cupola of Longview!"  It is actually leaning!<br/><br/>I really hated those wires in the background and tried this thing from different angles. My other alternate was with a bunch of dead trees and that looked terrible! Lost all of the sky with that one.  The best shot would have been if I could have stood in the middle of the street, but alas traffic wouldn''t stop for the challenge! LOL!!  <br/><br/>I have taken your comments and played around with the pic using some PhotoStudio enhancers and it does look better, I was even able to get those pesky wires out of the background!! So thanks again for all the comments!</td>', 'Thanks for all the comments!  It''s not the "leaning tower of Piza" but I guess you could say it is the "leaning cupola of Longview!"  It is actually leaning!I really hated those wires in the background and tried this thing from different angles. My other alternate was with a bunch of dead trees and that looked terrible! Lost all of the sky with that one.  The best shot would have been if I could have stood in the middle of the street, but alas traffic wouldn''t stop for the challenge! LOL!!  I have taken your comments and played around with the pic using some PhotoStudio enhancers and it does look better, I was even able to get those pesky wires out of the background!! So thanks again for all the comments!', '2002-04-08 13:09:00.000000', NULL, 0),
(43230, 548, 352, '<td valign="top">Nice ingenuity!  Shows that any of these challenges CAN be done from where you are.  Well done as well!!</td>', 'Nice ingenuity!  Shows that any of these challenges CAN be done from where you are.  Well done as well!!', '2002-04-01 01:50:00.000000', NULL, 1),
(43231, 548, 245, '<td valign="top">this is really neat, the shadow along the top edge adds a great touch.</td>', 'this is really neat, the shadow along the top edge adds a great touch.', '2002-04-01 02:41:00.000000', NULL, 1),
(43232, 548, 270, '<td valign="top">If only it was gingerbread..</td>', 'If only it was gingerbread..', '2002-04-01 02:45:00.000000', NULL, 1),
