(43234, 548, 92, '<td valign="top">Simple....yes speaks volumes ! I love this !!!! The shapes, shadows...it''s a great capture !</td>', 'Simple....yes speaks volumes ! I love this !!!! The shapes, shadows...it''s a great capture !', '2002-04-01 08:08:00.000000', NULL, 1),
