(43413, 561, 813, '<td valign="top">Nice composition and clever interpretation of the assignment.</td>', 'Nice composition and clever interpretation of the assignment.', '2002-04-06 21:44:00.000000', NULL, 1),
(43414, 561, 657, '<td valign="top">Coral is one of nature''s sky scrapers.  Millions of little animals live in it, and build it as they go.  Another one might be an ant hill or termite mound.  The perspective was made to look like you were looking up at something very tall.  Coral is made from calcium carbonate.</td>', 'Coral is one of nature''s sky scrapers.  Millions of little animals live in it, and build it as they go.  Another one might be an ant hill or termite mound.  The perspective was made to look like you were looking up at something very tall.  Coral is made from calcium carbonate.', '2002-04-08 18:10:00.000000', NULL, 0),
(43415, 562, 245, '<td valign="top">great title!</td>', 'great title!', '2002-04-01 01:55:00.000000', NULL, 1),
