(43435, 562, 797, '<td valign="top">lacks persepctive. would''ve been better if you cropped in to the street, framed by the buildings immediately adjacent to it.</td>', 'lacks persepctive. would''ve been better if you cropped in to the street, framed by the buildings immediately adjacent to it.', '2002-04-06 11:48:00.000000', NULL, 1),
(43436, 562, 813, '<td valign="top">Now here''s a shot that gets better when enlarged. Good energy! Captures the shimmer and vibrancy of a hundred years of architecture in Gotham. Bravo! Is there more detail in the original?</td>', 'Now here''s a shot that gets better when enlarged. Good energy! Captures the shimmer and vibrancy of a hundred years of architecture in Gotham. Bravo! Is there more detail in the original?', '2002-04-06 22:47:00.000000', NULL, 1),
(43437, 562, 543, '<td valign="top">Good clarity, and I love the composition (esp the street running right up the third to the Chrysler).  Sky looks a little blown out, depending on what the weather was like that day, but good colors right there on the horizon.</td>', 'Good clarity, and I love the composition (esp the street running right up the third to the Chrysler).  Sky looks a little blown out, depending on what the weather was like that day, but good colors right there on the horizon.', '2002-04-07 09:07:00.000000', NULL, 1),
(43438, 563, 352, '<td valign="top">Wow.  Excellent exposure here, perfect B&amp;W subject!  Way to go!</td>', 'Wow.  Excellent exposure here, perfect B&W subject!  Way to go!', '2002-04-01 02:00:00.000000', NULL, 1),
(43439, 563, 245, '<td valign="top">great contrast, and a really crazy barn! I''d try moving it *slightly* more towards the center to balance the image a bit more, maybe getting rid of the tree against the right edge in the process.</td>', 'great contrast, and a really crazy barn! I''d try moving it *slightly* more towards the center to balance the image a bit more, maybe getting rid of the tree against the right edge in the process.', '2002-04-01 02:29:00.000000', NULL, 1),
(43440, 563, 524, '<td valign="top">This is one of my favorite pictures.  I like the shadows on the house and the trees.</td>', 'This is one of my favorite pictures.  I like the shadows on the house and the trees.', '2002-04-01 02:44:00.000000', NULL, 1),
