(43448, 563, 557, '<td valign="top">hey! nice pic and i think you are charm like your presentation...anddd, i really like the shadow on the architecture</td>', 'hey! nice pic and i think you are charm like your presentation...anddd, i really like the shadow on the architecture', '2002-04-01 22:15:00.000000', NULL, 1),
(43449, 563, 428, '<td valign="top">Your choice of B&amp;W was excellent for ths shot! Looks like it could have been taken 75 years ago!  This is one of my favorites, great composition, terrific lighting. A winner in my book!</td>', 'Your choice of B&W was excellent for ths shot! Looks like it could have been taken 75 years ago!  This is one of my favorites, great composition, terrific lighting. A winner in my book!', '2002-04-01 23:04:00.000000', NULL, 1),
(43450, 563, 708, '<td valign="top">seems like it should be on a commercial</td>', 'seems like it should be on a commercial', '2002-04-02 08:32:00.000000', NULL, 1),
(43451, 563, 330, '<td valign="top">I like the shadows and B&amp;W in this picture. The architecture os so so.</td>', 'I like the shadows and B&W in this picture. The architecture os so so.', '2002-04-02 08:49:00.000000', NULL, 1),
(43452, 563, 549, '<td valign="top">nice work.</td>', 'nice work.', '2002-04-02 09:11:00.000000', NULL, 1),
(43453, 563, 1, '<td valign="top">Nicely done.  The clear sky, the early/late day lighting is a nice touch.  The b/w fits it perfectly.</td>', 'Nicely done.  The clear sky, the early/late day lighting is a nice touch.  The b/w fits it perfectly.', '2002-04-02 09:33:00.000000', NULL, 1),
