(43824, 595, 603, '<td valign="top">it is like the emerald city or something..some great modern-day palace..</td>', 'it is like the emerald city or something..some great modern-day palace..', '2002-04-01 01:36:00.000000', NULL, 1),
(43825, 595, 356, '<td valign="top">could use more contrast.</td>', 'could use more contrast.', '2002-04-01 01:51:00.000000', NULL, 1),
(43826, 595, 245, '<td valign="top">If you''re going for crazy symmetry, you should have the building appear to sit *completely* vertical, it feels tilted to the right. I''d love to see this shot taken on a calm day, with a clear reflection in the water! A more dramatic sky could improve it a lot, too.</td>', 'If you''re going for crazy symmetry, you should have the building appear to sit *completely* vertical, it feels tilted to the right. I''d love to see this shot taken on a calm day, with a clear reflection in the water! A more dramatic sky could improve it a lot, too.', '2002-04-01 02:00:00.000000', NULL, 1),
(43827, 595, 352, '<td valign="top">Great job framing this!</td>', 'Great job framing this!', '2002-04-01 02:36:00.000000', NULL, 1),
(43828, 595, 270, '<td valign="top">What a gorgeous photograph.  I feel like I''m in Oz..</td>', 'What a gorgeous photograph.  I feel like I''m in Oz..', '2002-04-01 02:52:00.000000', NULL, 1),
(43829, 595, 291, '<td valign="top">Wow, nice subject, just needs a little more contrast</td>', 'Wow, nice subject, just needs a little more contrast', '2002-04-01 03:01:00.000000', NULL, 1),
(43830, 595, 308, '<td valign="top">Beautiful picture.  I don''t know which is more eerie - the almost perfect symmetry or the absolute lack of people!  Where is everyone?</td>', 'Beautiful picture.  I don''t know which is more eerie - the almost perfect symmetry or the absolute lack of people!  Where is everyone?', '2002-04-01 07:55:00.000000', NULL, 1),
(43831, 595, 714, '<td valign="top">you were in the right spot for this shot</td>', 'you were in the right spot for this shot', '2002-04-01 08:43:00.000000', NULL, 1),
(43832, 595, 472, '<td valign="top">indeed you have captured the symmetry well!</td>', 'indeed you have captured the symmetry well!', '2002-04-01 08:48:00.000000', NULL, 1),
(43833, 595, 441, '<td valign="top">spectacular modern day building - cracking example</td>', 'spectacular modern day building - cracking example', '2002-04-01 11:28:00.000000', NULL, 1),
(43834, 595, 54, '<td valign="top">This doesn''t even look real! It looks like one of those perfect future societies.  Very nice!</td>', 'This doesn''t even look real! It looks like one of those perfect future societies.  Very nice!', '2002-04-01 13:09:00.000000', NULL, 1),
(43835, 595, 142, '<td valign="top">Yes it is symetric.  Where is this?  It looks like a 21st century version of the Taj Mahal.</td>', 'Yes it is symetric.  Where is this?  It looks like a 21st century version of the Taj Mahal.', '2002-04-01 16:22:00.000000', NULL, 1),
(43836, 595, 428, '<td valign="top">I love this picture! Excellent!! Great framing, beautiful subject!  The only drawback is that it might be a little dark, but I guess that''s because it was cloudy?</td>', 'I love this picture! Excellent!! Great framing, beautiful subject!  The only drawback is that it might be a little dark, but I guess that''s because it was cloudy?', '2002-04-01 18:48:00.000000', NULL, 1),
