(43838, 595, 330, '<td valign="top">The symmetry works well here, shame it wasn''t a brighter day.</td>', 'The symmetry works well here, shame it wasn''t a brighter day.', '2002-04-02 08:46:00.000000', NULL, 1),
(43839, 595, 549, '<td valign="top">nice shot but too bad the sky was so washed out. This happens to me all the time. Just not the right day, or time of day.</td>', 'nice shot but too bad the sky was so washed out. This happens to me all the time. Just not the right day, or time of day.', '2002-04-02 08:46:00.000000', NULL, 1),
(43840, 595, 346, '<td valign="top">nice view. I think the pic might have been stronger if it was taken with the camera on its side, and focused solely on the main building, trees and the water.</td>', 'nice view. I think the pic might have been stronger if it was taken with the camera on its side, and focused solely on the main building, trees and the water.', '2002-04-02 12:43:00.000000', NULL, 1),
(43841, 595, 705, '<td valign="top">nice setup; the tiniest bit crooked; it''s like some kind of contemporary wonderland, a nice feeling; the colors run together a little bit, I guess that''s the tones, maybe?</td>', 'nice setup; the tiniest bit crooked; it''s like some kind of contemporary wonderland, a nice feeling; the colors run together a little bit, I guess that''s the tones, maybe?', '2002-04-02 12:59:00.000000', NULL, 1),
