(43843, 595, 279, '<td valign="top">Too simple, and the subject''s too far back.</td>', 'Too simple, and the subject''s too far back.', '2002-04-03 13:06:00.000000', NULL, 1),
(43844, 595, 637, '<td valign="top">Yes, its symmetric but otherwise not very interesting...  I want there to be more life (i.e., people) and brigher colors.  (BTW, my dtr disagrees with my assessment of the colors!)</td>', 'Yes, its symmetric but otherwise not very interesting...  I want there to be more life (i.e., people) and brigher colors.  (BTW, my dtr disagrees with my assessment of the colors!)', '2002-04-03 13:45:00.000000', NULL, 1),
