(43846, 595, 1, '<td valign="top">Very nice image.  Perfectly centered.  I just wish it was on a clearer day -- the impact would''ve been so much more.</td>', 'Very nice image.  Perfectly centered.  I just wish it was on a clearer day -- the impact would''ve been so much more.', '2002-04-04 07:56:00.000000', NULL, 1),
(43847, 595, 570, '<td valign="top">wtf is that?</td>', 'wtf is that?', '2002-04-04 14:22:00.000000', NULL, 1),
