(43849, 595, 587, '<td valign="top">Great photo!!</td>', 'Great photo!!', '2002-04-05 16:00:00.000000', NULL, 1),
(43850, 595, 554, '<td valign="top">Architecture,leading lines,good angle and framing. Good one!</td>', 'Architecture,leading lines,good angle and framing. Good one!', '2002-04-06 19:50:00.000000', NULL, 1),
(43851, 595, 447, '<td valign="top">Nice detail, but the building is a little too centered in the picture</td>', 'Nice detail, but the building is a little too centered in the picture', '2002-04-06 20:44:00.000000', NULL, 1),
(43852, 595, 543, '<td valign="top">Okay, you got me.  Where is this?  Very interesting.</td>', 'Okay, you got me.  Where is this?  Very interesting.', '2002-04-07 09:38:00.000000', NULL, 1),
(43853, 595, 820, '<td valign="top">Nice - needs contrast, though.</td>', 'Nice - needs contrast, though.', '2002-04-07 12:34:00.000000', NULL, 1),
(43854, 595, 280, '<td valign="top">Wow 6th, I didnt think this would come so high. The picture was taken in Salford Quays (Manchester, England), Its a housing and business development, built on old dock land, hence the canal. The buildings hidden by trees were partially designed my farther, who was an architect until he retired. The total lack of people isnt abnormal its usually like this, although the houses are mostly inhabited there is hardly ever anybody on the streets, which always makes it seem slightly spooky. And thank you for all the comments about the sky, It had been really nice weather all week until my day off which was overcast. Doh!</td>', 'Wow 6th, I didnt think this would come so high. The picture was taken in Salford Quays (Manchester, England), Its a housing and business development, built on old dock land, hence the canal. The buildings hidden by trees were partially designed my farther, who was an architect until he retired. The total lack of people isnt abnormal its usually like this, although the houses are mostly inhabited there is hardly ever anybody on the streets, which always makes it seem slightly spooky. And thank you for all the comments about the sky, It had been really nice weather all week until my day off which was overcast. Doh!', '2002-04-08 03:09:00.000000', NULL, 0),
(43855, 596, 603, '<td valign="top">i love the subject of the photo..</td>', 'i love the subject of the photo..', '2002-04-01 01:28:00.000000', NULL, 1),
(43856, 596, 352, '<td valign="top">The subject here is more sculpture than architecture.</td>', 'The subject here is more sculpture than architecture.', '2002-04-01 01:40:00.000000', NULL, 1),
(43857, 596, 245, '<td valign="top">it feels a bit soft, did you try sharpening?</td>', 'it feels a bit soft, did you try sharpening?', '2002-04-01 02:50:00.000000', NULL, 1),
(43858, 596, 270, '<td valign="top">Obviously a great sense of action, but the chromatic aberrations through the trees are very distracting.</td>', 'Obviously a great sense of action, but the chromatic aberrations through the trees are very distracting.', '2002-04-01 03:08:00.000000', NULL, 1),
(43859, 596, 291, '<td valign="top">More art than architecture, Nice pic! glad you got out of the way in time!</td>', 'More art than architecture, Nice pic! glad you got out of the way in time!', '2002-04-01 03:14:00.000000', NULL, 1),
(43860, 596, 1, '<td valign="top">Good interpretation, although I feel that a horizontal image would''ve worked better in different lighting.</td>', 'Good interpretation, although I feel that a horizontal image would''ve worked better in different lighting.', '2002-04-01 08:18:00.000000', NULL, 1);
