(43864, 596, 509, '<td valign="top">Aw, when I read the title, I was hoping for Ford Mustangs, j/k</td>', 'Aw, when I read the title, I was hoping for Ford Mustangs, j/k', '2002-04-01 11:39:00.000000', NULL, 1),
(43865, 596, 441, '<td valign="top">Impression of galloping horses looks real, interesting reflections in windows.</td>', 'Impression of galloping horses looks real, interesting reflections in windows.', '2002-04-01 12:18:00.000000', NULL, 1),
