(43867, 596, 718, '<td valign="top">That''s a sweet fountain.  They look like they are coming at me!</td>', 'That''s a sweet fountain.  They look like they are coming at me!', '2002-04-01 13:53:00.000000', NULL, 1),
(43868, 596, 544, '<td valign="top">great picture! maybe a shot from below, looking up, and a little tighter cropping? nice :)</td>', 'great picture! maybe a shot from below, looking up, and a little tighter cropping? nice :)', '2002-04-01 18:30:00.000000', NULL, 1),
(43869, 596, 308, '<td valign="top">Excellent - those are fountains?  Great angle.</td>', 'Excellent - those are fountains?  Great angle.', '2002-04-01 18:40:00.000000', NULL, 1),
