(43871, 596, 330, '<td valign="top">I like it, but seems more like sculpture</td>', 'I like it, but seems more like sculpture', '2002-04-02 08:45:00.000000', NULL, 1),
(43872, 596, 549, '<td valign="top">good shot, nice eye for the correct angle. Or I should say a good choice of angle. Too bad the sky is not blue. That of helped but not your fault the weather wasn''t on your side.</td>', 'good shot, nice eye for the correct angle. Or I should say a good choice of angle. Too bad the sky is not blue. That of helped but not your fault the weather wasn''t on your side.', '2002-04-02 09:00:00.000000', NULL, 1),
