(43874, 596, 656, '<td valign="top">good sense of motion - might have been even stronger at more of an angle, rather than straight on ?</td>', 'good sense of motion - might have been even stronger at more of an angle, rather than straight on ?', '2002-04-02 14:43:00.000000', NULL, 1),
(43875, 596, 527, '<td valign="top">Great picture but the focus is clearly sculpture and not architecture.</td>', 'Great picture but the focus is clearly sculpture and not architecture.', '2002-04-02 17:52:00.000000', NULL, 1),
(43876, 596, 227, '<td valign="top">One of my favorite subjects.  write and I will send you a couple of cool shots.  baxterbrinkley@att.net<br/></td>', 'One of my favorite subjects.  write and I will send you a couple of cool shots.  baxterbrinkley@att.net', '2002-04-03 13:52:00.000000', NULL, 1),
(43877, 596, 772, '<td valign="top">That is one of the coolest water sculptures I have ever seen...</td>', 'That is one of the coolest water sculptures I have ever seen...', '2002-04-03 16:45:00.000000', NULL, 1),
(43878, 596, 570, '<td valign="top">cool</td>', 'cool', '2002-04-04 14:22:00.000000', NULL, 1),
(43879, 596, 813, '<td valign="top">This shot could be dramatically improved by cropping two inches off the top (just above the horses heads) and either leveling it or tilting a bit more off level. Leaving the steps in the foreground would still qualify it for architecture.  Where is this scene?</td>', 'This shot could be dramatically improved by cropping two inches off the top (just above the horses heads) and either leveling it or tilting a bit more off level. Leaving the steps in the foreground would still qualify it for architecture.  Where is this scene?', '2002-04-06 22:59:00.000000', NULL, 1),
(43880, 596, 820, '<td valign="top">If ever a photo needed depth of field, this is it. A lower point of view would help too.</td>', 'If ever a photo needed depth of field, this is it. A lower point of view would help too.', '2002-04-07 12:26:00.000000', NULL, 1),
(43881, 597, 245, '<td valign="top">This looks so good, nice and soft, fantastic colors... even the tracks in the snow... wow! Why did you leave the little dark bit in the bottom right corner? Does it make the roof of the building look funny when cropped? :)</td>', 'This looks so good, nice and soft, fantastic colors... even the tracks in the snow... wow! Why did you leave the little dark bit in the bottom right corner? Does it make the roof of the building look funny when cropped? :)', '2002-04-01 01:54:00.000000', NULL, 1),
(43882, 597, 352, '<td valign="top">Oh no, not another cross... =)</td>', 'Oh no, not another cross... =)', '2002-04-01 02:18:00.000000', NULL, 1),
(43883, 597, 270, '<td valign="top">Awe-inspiring how the clouds are perfectly white above, matching with the snow.</td>', 'Awe-inspiring how the clouds are perfectly white above, matching with the snow.', '2002-04-01 03:09:00.000000', NULL, 1),
(43884, 597, 472, '<td valign="top">very cool pic. nice contrast with the other skyscrapers and stuff.</td>', 'very cool pic. nice contrast with the other skyscrapers and stuff.', '2002-04-01 08:16:00.000000', NULL, 1),
(43885, 597, 714, '<td valign="top">great lighting, unique way to capture the challenge and all around great photo</td>', 'great lighting, unique way to capture the challenge and all around great photo', '2002-04-01 09:48:00.000000', NULL, 1),
(43886, 597, 326, '<td valign="top">I really enjoyed this shot!</td>', 'I really enjoyed this shot!', '2002-04-01 10:11:00.000000', NULL, 1),
