(43888, 597, 705, '<td valign="top">a bit dark; great subject; I love the sky-although the cross gets a bit lost in it; there''s perhaps too much going on-the house, the rock, the gazebo, the red roof, the sky and the footprints</td>', 'a bit dark; great subject; I love the sky-although the cross gets a bit lost in it; there''s perhaps too much going on-the house, the rock, the gazebo, the red roof, the sky and the footprints', '2002-04-01 13:02:00.000000', NULL, 1),
(43889, 597, 441, '<td valign="top">good interesting shot</td>', 'good interesting shot', '2002-04-01 15:33:00.000000', NULL, 1),
