(44041, 610, 428, '<td valign="top">I like this photo, the trees give good framing.  I''m bothered by the darkness of the bottom of the house. Looks like too much shadow, but not sure how to compensate for that.</td>', 'I like this photo, the trees give good framing.  I''m bothered by the darkness of the bottom of the house. Looks like too much shadow, but not sure how to compensate for that.', '2002-04-01 22:34:00.000000', NULL, 1),
(44042, 610, 689, '<td valign="top">The foreground is a little busy ... esp with all the other branches on the trees .... try it in B&amp;W too!</td>', 'The foreground is a little busy ... esp with all the other branches on the trees .... try it in B&W too!', '2002-04-01 23:13:00.000000', NULL, 1),
(44043, 610, 330, '<td valign="top">Nicely framed. Not sure about the "architecture.</td>', 'Nicely framed. Not sure about the "architecture.', '2002-04-02 08:50:00.000000', NULL, 1),
(44044, 610, 54, '<td valign="top">Reminds me of the cabin in Evil Dead. Cool.</td>', 'Reminds me of the cabin in Evil Dead. Cool.', '2002-04-02 09:39:00.000000', NULL, 1),
