(44048, 610, 313, '<td valign="top">the mere sight of that building gives me the heebie-jeebies.</td>', 'the mere sight of that building gives me the heebie-jeebies.', '2002-04-03 22:21:00.000000', NULL, 1),
(44049, 610, 113, '<td valign="top">Nice framing.  Good photo.</td>', 'Nice framing.  Good photo.', '2002-04-05 03:06:00.000000', NULL, 1),
(44050, 610, 797, '<td valign="top">the detail is amazing. unfortunately the foreground logs are distracting from the subject.</td>', 'the detail is amazing. unfortunately the foreground logs are distracting from the subject.', '2002-04-06 11:53:00.000000', NULL, 1),
(44051, 612, 603, '<td valign="top">one of my favorites..something shot clearly and not the same as the rest..</td>', 'one of my favorites..something shot clearly and not the same as the rest..', '2002-04-01 01:35:00.000000', NULL, 1),
