(44057, 612, 346, '<td valign="top">focal point seems just in front of the center piece of the swirl. Also, higher contrast might have brought out more. Great pic though.</td>', 'focal point seems just in front of the center piece of the swirl. Also, higher contrast might have brought out more. Great pic though.', '2002-04-02 16:44:00.000000', NULL, 1),
(44058, 612, 772, '<td valign="top">I''m inspired by this photo... I love it and it has my best rating so far....</td>', 'I''m inspired by this photo... I love it and it has my best rating so far....', '2002-04-03 16:31:00.000000', NULL, 1),
(44059, 612, 313, '<td valign="top">this is a very pretty shot.  probably fits well (maybe better) in the next challenge, though.  heh.  regardless, i like it a lot.</td>', 'this is a very pretty shot.  probably fits well (maybe better) in the next challenge, though.  heh.  regardless, i like it a lot.', '2002-04-03 22:19:00.000000', NULL, 1),
(44060, 612, 1, '<td valign="top">Seems a little hazy.  Maybe darken it?</td>', 'Seems a little hazy.  Maybe darken it?', '2002-04-04 08:17:00.000000', NULL, 1),
