INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(44077, 615, 472, '<td valign="top">nice pic. might want to increase the contrast tho. altho in retro, i like the delicate lighting ...</td>', 'nice pic. might want to increase the contrast tho. altho in retro, i like the delicate lighting ...', '2002-04-01 08:15:00.000000', NULL, 1),
(44078, 615, 441, '<td valign="top">nice composition</td>', 'nice composition', '2002-04-01 11:21:00.000000', NULL, 1),
(44079, 615, 596, '<td valign="top">Nice repetition.</td>', 'Nice repetition.', '2002-04-01 11:39:00.000000', NULL, 1),
(44080, 615, 449, '<td valign="top">not enough contrast. no true blacks and whites. just varying greys. not a bad idea.</td>', 'not enough contrast. no true blacks and whites. just varying greys. not a bad idea.', '2002-04-01 12:10:00.000000', NULL, 1),
(44081, 615, 203, '<td valign="top">I love the composition but it seems flat overall.</td>', 'I love the composition but it seems flat overall.', '2002-04-01 13:27:00.000000', NULL, 1),
(44082, 615, 259, '<td valign="top">kind of boaring and you can''t really see whats going on down by the light</td>', 'kind of boaring and you can''t really see whats going on down by the light', '2002-04-01 15:10:00.000000', NULL, 1),
(44083, 615, 102, '<td valign="top">Was this shot black and white, or was it done in very very low light w/ an odd white balance?  If the former, it would benefit from increased contrast (preferably when the shot was taken, so the "light" would be more visible and clearer), if the later than it would have been better to go with full color, or at least more color than you have...</td>', 'Was this shot black and white, or was it done in very very low light w/ an odd white balance?  If the former, it would benefit from increased contrast (preferably when the shot was taken, so the "light" would be more visible and clearer), if the later than it would have been better to go with full color, or at least more color than you have...', '2002-04-01 16:08:00.000000', NULL, 1),
(44084, 615, 2, '<td valign="top">Very good composition -- the pattern of repeating shapes really draws you in.  Slightly tilted to the left, though.</td>', 'Very good composition -- the pattern of repeating shapes really draws you in.  Slightly tilted to the left, though.', '2002-04-01 19:25:00.000000', NULL, 1),
(44085, 615, 428, '<td valign="top">a little too dark for me, and I would have moved about one step to the right to get a little better symmetry with the light sconces on the wall. Good try!</td>', 'a little too dark for me, and I would have moved about one step to the right to get a little better symmetry with the light sconces on the wall. Good try!', '2002-04-01 23:10:00.000000', NULL, 1),
(44086, 615, 689, '<td valign="top">needs to be a little lighter ... its all grey, no real whites. The trick with b&amp;w is to have true white and true black in the photograph. The symetry of the composition is nice!</td>', 'needs to be a little lighter ... its all grey, no real whites. The trick with b&w is to have true white and true black in the photograph. The symetry of the composition is nice!', '2002-04-01 23:20:00.000000', NULL, 1),
(44087, 615, 113, '<td valign="top">Could have been a little clearer and some more contrast would have been nice</td>', 'Could have been a little clearer and some more contrast would have been nice', '2002-04-02 05:10:00.000000', NULL, 1),
(44088, 615, 1, '<td valign="top">Slight centering problem, but for the most part it''s a good image.</td>', 'Slight centering problem, but for the most part it''s a good image.', '2002-04-02 08:06:00.000000', NULL, 1),
(44089, 615, 549, '<td valign="top">unfortunately you didn''t see the correct contrast. No real blacks and definitely no whites. My photo teacher in college would of killed me for this one.</td>', 'unfortunately you didn''t see the correct contrast. No real blacks and definitely no whites. My photo teacher in college would of killed me for this one.', '2002-04-02 08:58:00.000000', NULL, 1),
(44090, 615, 346, '<td valign="top">love the symmetry you were able to capture here.</td>', 'love the symmetry you were able to capture here.', '2002-04-02 12:53:00.000000', NULL, 1),
(44091, 615, 705, '<td valign="top">great set up; a bit hazy and dark</td>', 'great set up; a bit hazy and dark', '2002-04-02 13:13:00.000000', NULL, 1),
(44092, 615, 357, '<td valign="top">Seems a little under-exposed to me.</td>', 'Seems a little under-exposed to me.', '2002-04-02 15:56:00.000000', NULL, 1),
(44093, 615, 291, '<td valign="top">no contrast, look kind of flat</td>', 'no contrast, look kind of flat', '2002-04-03 00:04:00.000000', NULL, 1),
(44094, 615, 156, '<td valign="top">interesting but needs more contrast</td>', 'interesting but needs more contrast', '2002-04-03 10:13:00.000000', NULL, 1),
