(44100, 616, 352, '<td valign="top">Your analogy of this picture''s fitenss for architecture is lost on me, despite your title.</td>', 'Your analogy of this picture''s fitenss for architecture is lost on me, despite your title.', '2002-04-01 01:30:00.000000', NULL, 1),
(44101, 616, 536, '<td valign="top">I wasn''t convinced that this picture met the challenge.</td>', 'I wasn''t convinced that this picture met the challenge.', '2002-04-01 12:28:00.000000', NULL, 1),
(44102, 616, 203, '<td valign="top">Interesting stretch on the theme but too far for me.</td>', 'Interesting stretch on the theme but too far for me.', '2002-04-01 13:53:00.000000', NULL, 1),
(44103, 616, 549, '<td valign="top">nice idea just not pulled off well. The guitar doesn''t show up much on that background. The lighting isn''t very interesting nor is the angle.</td>', 'nice idea just not pulled off well. The guitar doesn''t show up much on that background. The lighting isn''t very interesting nor is the angle.', '2002-04-02 09:08:00.000000', NULL, 1),
