(44108, 616, 113, '<td valign="top">Sorry dude, I see no architecture here.</td>', 'Sorry dude, I see no architecture here.', '2002-04-03 07:01:00.000000', NULL, 1),
(44109, 616, 127, '<td valign="top">I don''t get it....... are you or is it your guitar that''s supposed to represent the "architecture of rock and roll"?</td>', 'I don''t get it....... are you or is it your guitar that''s supposed to represent the "architecture of rock and roll"?', '2002-04-06 04:08:00.000000', NULL, 1),
